import{_ as t,o as e,c as a,Q as i}from"./chunks/framework.b67c47e6.js";const f=JSON.parse('{"title":"Isolation machine","description":"","frontmatter":{},"headers":[],"relativePath":"guide/machine_files/machines/isolation/index.md","filePath":"guide/machine_files/machines/isolation/index.md","lastUpdated":1790618281000}'),o={name:"guide/machine_files/machines/isolation/index.md"},n=i('<h1 id="isolation-machine" tabindex="-1">Isolation machine <a class="header-anchor" href="#isolation-machine" aria-label="Permalink to &quot;Isolation machine&quot;">​</a></h1><p>The H&amp;M Isolation machine blows loose insulation, such as cellulose, into the cavities of the frame. Its head carries a row of nozzles and fills one or several cavities from each position. It is a station of an H&amp;M line, and its layer is written into the panel&#39;s <a href="/guide/machine_files/formats/panel_mob2/">MOB v2 file</a> together with those of the other stations.</p><nav class="table-of-contents"><ul><li><a href="#setting-it-up">Setting it up</a></li><li><a href="#which-parts-are-filled">Which parts are filled</a></li><li><a href="#machine-setup">Machine setup</a></li><li><a href="#what-it-writes">What it writes</a></li><li><a href="#job-options">Job options</a></li><li><a href="#drawings">Drawings</a></li></ul></nav><h2 id="setting-it-up" tabindex="-1">Setting it up <a class="header-anchor" href="#setting-it-up" aria-label="Permalink to &quot;Setting it up&quot;">​</a></h2><ol><li>In <strong>Production Settings &gt; Machine Settings</strong>, create a setup with the model <em>H&amp;M Isolation Machine</em>.</li><li>Upload the machine&#39;s configuration file (XML) in the <strong>Machine file</strong> tab.</li><li>In <strong>Production lines</strong>, link the setup to a station with <strong>Machine station</strong>. Give it zone 1 or -1, the face it fills from.</li></ol><h2 id="which-parts-are-filled" tabindex="-1">Which parts are filled <a class="header-anchor" href="#which-parts-are-filled" aria-label="Permalink to &quot;Which parts are filled&quot;">​</a></h2><p>Only the insulation areas your parsing setup marks for the machine: the <strong>Isolated Area</strong> category, plus the <strong>Isolation: Machine Flag</strong> rule of the Operations and machines tab. The <strong>Isolation order number</strong> property can set the order in which they are filled.</p><p>See: <a href="/guide/management/ifcps/#isolation-machine-flag">IFC Parsing Setup</a></p><h2 id="machine-setup" tabindex="-1">Machine setup <a class="header-anchor" href="#machine-setup" aria-label="Permalink to &quot;Machine setup&quot;">​</a></h2><table><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Switch direction X-axis</strong>, <strong>Switch direction Y-axis</strong>, <strong>Machine zero</strong></td><td>The orientation and the zero of the machine, as on the <a href="/guide/machine_files/machines/mobi_one/#machine-setup">Mobi One</a>.</td></tr><tr><td><strong>Materials</strong></td><td>Which machine material index each insulation material of the model uses. By default <code>CELLULOSE</code> is material 1.</td></tr><tr><td><strong>Material densities</strong></td><td>The density of each machine material, in kg/m³. The weight written for each shot comes from it.</td></tr><tr><td><strong>Bottom overlap</strong>, <strong>Top overlap</strong></td><td>How far the filling reaches past the bottom and the top of each cavity, in mm.</td></tr><tr><td><strong>Head allowed directions</strong></td><td><em>horizontal</em>, <em>vertical</em> or <em>both</em> (the default): the directions the head may be turned to.</td></tr><tr><td><strong>Machine type</strong></td><td>The head: 7 nozzles (the default), 8 nozzles or 6 nozzles.</td></tr><tr><td><strong>Use TSP optimizer</strong></td><td>Orders the head positions to shorten the travel. Its weights, speeds and time limit are set next to it.</td></tr></tbody></table><h2 id="what-it-writes" tabindex="-1">What it writes <a class="header-anchor" href="#what-it-writes" aria-label="Permalink to &quot;What it writes&quot;">​</a></h2><p>One layer named <em>Isolation 1</em>, with one <code>INS</code> row per head position: where the head stands, whether it is turned, which nozzles are open, and the weight to blow.</p><h2 id="job-options" tabindex="-1">Job options <a class="header-anchor" href="#job-options" aria-label="Permalink to &quot;Job options&quot;">​</a></h2><p><strong>Production starting side</strong>, <strong>Shift mode</strong>, and <strong>Export Isolation as CSV</strong>, which adds a CSV file of the head positions next to the MOB v2 file in the ZIP.</p><h2 id="drawings" tabindex="-1">Drawings <a class="header-anchor" href="#drawings" aria-label="Permalink to &quot;Drawings&quot;">​</a></h2><p>With the report comes an <strong>Isolation</strong> drawing of the head positions, when the <strong>SVG Drawings</strong> switches of the station that owns zone 0 allow it.</p>',16),s=[n];function r(h,l,d,c,m,g){return e(),a("div",null,s)}const u=t(o,[["render",r]]);export{f as __pageData,u as default};
